import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xC128,0xC129,'data','Modo della finestra sorgente: largo0 / stretto nonzero'),(0xC129,0xC160,'code','Controlli della finestra e inizializzazione tramite C142'),(0xA277,0xA296,'code','Schermo per immagine: pulizia e ingresso a18 colonne'),(0xC2CA,0xC306,'code','Linefeed: contatore MORE e ripristino della larghezza'),(0xC306,0xC37D,'code','MORE: ritorno largo; scroll parziale o completo'),(0xD719,0xD726,'code','Input accettato: azzera il contatore e chiama C142')]
notes={0xC128:'Dato mutabile, non parte di un’istruzione.0=36 colonne,nonzero=18. Il profilo canonico corrente disabilita la grafica originale; la scelta SVG/pixel della UI non cambia questo byte.',0xC129:'Controllo stretto: reset esplicitoA019 e modo1. Non equivale al solo cambio del numero di colonne.',0xC12E:'Writer del modo stretto:1 daINC A dopoXOR A.',0xC133:'Ingresso comune: colonne residue dal valoreA fornito dal controllo, originebitmap5020, shift2. Non svuotaA9B5 né il buffer parole.',0xC142:'Controllo largo:0 nel modo e36 colonne. NON azzeraA019; non inferire il valore del contatore dalla larghezza.',0xC143:'Writer largo: stesso0 anche se il modo era già0. Tracciati gli store invariati, non soltanto le transizioni.',0xC15D:'Inizializzazione dello schermo: chiamaC142 prima della stampa iniziale. Questo writer possiede il flag nell’avvio JS; nessun fallback del payload sui vecchiLOAD.',0xA284:'Dopo la pulizia per la figura entraC129: la finestra stretta del gioco originale dipende dal percorso grafico, non dalle preferenze della pagina web.',0xC2CD:'MORE si attiva quandoA019 èesattamente15, prima dello scroll pendente.',0xC2D4:'DopoMORE:A019=FF, poiINC ->00. C306 da solo non scrive il contatore.',0xC2E2:'La larghezza viene riletta dopoC316 e l’eventualeMORE, che può averla riportata a36.',0xC306:'FLASH dell’ultima cella della barra; attesa del tasto e ritorno aC142. Controlli ABI conSPACE immediato secondo il protocollo dichiarato.',0xC311:'MORE scrive il modo0 tramiteC142; il prompt e una normale CR senzaMORE non sono writer diC128.',0xC316:'In modo largo gestisce la stampante e copia32byte per scan; stretto16byte. Il dossier non certifica i bitmap del profilo nativo con immagini.',0xC363:'Pulisce36 o18 caratteri secondo il modo rimasto dopoMORE.',0xD71A:'Questo reset del contatore appartiene all’input accettato, non aC142. Gli errori lessicali possono non arrivare aD719.',0xD71D:'Writer largo tramiteC142 anche se il flag valeva già0. VecchiLOAD senza il campo tornano posseduti soltanto a un writer compreso.'}
fields={0xC128:[['0','36 colonne','Profilo sorgente canonico senza grafica originale; indipendente dal browser'],['1 / nonzero','18 colonne','IngressoC129 per immagini; controlli logici verificati, nessun certificato completo dei bitmap nativi stretti'],['Writer','C12E eC143','18 resettaA019,36 lo preserva. Boot/parsing/MORE ristabiliscono0'],['LOAD','proprietà esplicita','Campo assente restaunknown fino al writer; non derivare daSVG/pixel o dal numero di caratteri di una riga']]}
lines=['; Dossier offline: dati e codice distinti; istruzioni riassellate contro il payload.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=min(8,b-at);op='DEFB '+','.join(f'${v:02X}'for v in m[at:at+n])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/text-window-mode';root.mkdir(exist_ok=True);(root/'text-window-mode.asm').write_text('\n'.join(lines)+'\n');(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=145,**({'fields':fields[a]}if a in fields else{}))for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
